Rules.InvariantScript:
Set(varMVF_Open, false);
Set(varMVF_Search, "");

ClearCollect(
    varMVF_Selected,
    FirstN(
        Table(
            {
                Id: "",
                Code: "",
                Display: "",
                SortOrder: 0
            }
        ),
        0
    )
);

ClearCollect(
    varMVF_Invalid,
    FirstN(
        Table({ Code: "" }),
        0
    )
)

If(
    IsBlank(
        LookUp(
            varMVF_Selected,
            Code = ThisItem.Code
        )
    ),
    Collect(
        varMVF_Selected,
        {
            Id: ThisItem.Id,
            Code: ThisItem.Code,
            Display: ThisItem.Display,
            SortOrder: ThisItem.SortOrder
        }
    )
)

ClearCollect(
    varMVF_Selected,
    FirstN(
        Table(
            {
                Id: "",
                Code: "",
                Display: "",
                SortOrder: 0
            }
        ),
        0
    )
);

ClearCollect(
    varMVF_Invalid,
    FirstN(
        Table({ Code: "" }),
        0
    )
);

Set(varMVF_Search, "");

Reset(txtMVF_Search);
Reset(txtMVF_Paste);
Reset(galMVF_Items)

If(
    IsBlank(Trim(txtMVF_Paste.Text)),

    Reset(txtMVF_Paste);
    cmp_MultiValueFilter.OnClose(),

    With(
        {
            _rawCodes:
                ForAll(
                    Split(
                        Substitute(
                            Substitute(
                                Substitute(txtMVF_Paste.Text, Char(13), ""),
                                ";",
                                Char(10)
                            ),
                            ",",
                            Char(10)
                        ),
                        Char(10)
                    ),
                    { Code: Upper(Trim(Value)) }
                )
        },
        With(
            {
                _cleanCodes:
                    Distinct(
                        Filter(_rawCodes, !IsBlank(Code)),
                        Code
                    )
            },
            ClearCollect(
                varMVF_Selected,
                Filter(
                    cmp_MultiValueFilter.Items,
                    Code in _cleanCodes.Value
                )
            );

            ClearCollect(
                varMVF_Invalid,
                RenameColumns(
                    Filter(
                        _cleanCodes,
                        !(Value in cmp_MultiValueFilter.Items.Code)
                    ),
                    Value,
                    Code
                )
            );

            Reset(txtMVF_Paste);
            cmp_MultiValueFilter.OnClose()
        )
    )
)
